renvoAsmStorePrimaryStack(a, data)
renvoAsmLoadPrimaryStackMemory(a, lenSlot, 0)
renvoAsmStorePrimaryStack(a, length)
renvoAsmLoadPrimaryStackMemory(a, capSlot, 0)
renvoAsmStorePrimaryStack(a, capacity)

