renvoAsmLoadPrimaryStack(a, length)
renvoAsmCopyPrimaryToTertiary(a)
renvoAsmPrimaryImm(a, elemSize)
renvoRTGDirectMultiply(a, renvoRTGPrimary, renvoRTGTertiary)
