done := renvoAsmNewLabel(&g.asm)
renvoEmitNativeCompareStack(g, left-g.c.renvoNativeIntSize, right-g.c.renvoNativeIntSize, 0x94)
renvoAsmJnzPrimary(&g.asm, highEqual)
