func renvoKernelNameFromOutput(path string) string {
start := 0
for i := 0; i < len(path); i++ {
if path[i] == '/' || path[i] == '\\' {
start = i + 1
}
}
end := len(path)
if end-start > 3 && path[end-3] == '.' && path[end-2] == 'k' && path[end-1] == 'o' {
end -= 3
}
var out []byte
for i := start; i < end && len(out) < 55; i++ {
ch := path[i]
if ch >= 'A' && ch <= 'Z' || ch >= 'a' && ch <= 'z' || ch >= '0' && ch <= '9' || ch == '_' {
out = append(out, ch)
} else {
out = append(out, '_')
}
}
if len(out) == 0 {
return "renvo"
}
return string(out)
}

