symtab = renvoKernelAppendSym64(symtab, 0, 3, 3, 0, 0)
symtab = renvoKernelAppendSym64(symtab, 0, 3, 4, 0, 0)
symtab = renvoKernelAppendSym64(symtab, 0, 3, 7, 0, 0)
